FB->Axis_numOut = FB->Axis_num;//轴号不发生改变
#endif
}

FBDMC_MoveAbsolute(ePLCKernalSta *Task, Uint32 FBIndex,struct MC_MoveAbsolute *FB){
/*Separator--*--Separator--*--Separator*/
//void FBDMC_MoveAbsolute(ePLCKernalSta *Task, Uint32 FBIndex,struct MC_MoveAbsolute *FB){
#ifndef _CASS_PRECOMPILE_

//修改S型混承问题
//修改混承时的出buffer区的条件 （删去 *run_next == 0  该条件使功能块延迟一周期执行， 注：FB完成时 *run_next被赋值为1，在中被赋值为0，相当于每周期开始时为0
//修改混承的开始时间的计算
//20240817 修改mc_moveabsolute功能块，主要涉及if...else...，其它没改
//20240901修改位置相关变量单精度为双精度，包括引脚和临时变量

#define    tiqian_pos      0.05
#define    special_minv    0.008

uint8_t *state = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + STATE]);
double *target_position = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE*FB->Axis_num + TARGET_POSITION]);
double *now_position = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE*FB->Axis_num + NOW_POSITION]);
double *relative_position = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + RELATIVE_POSITION]);
float *now_velocity = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE*FB->Axis_num + NOW_VELOCITY]);
uint8_t *run_numberm = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + RUN_NUMBERM]);
double *last_target_position = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE*FB->Axis_num + LAST_TARGET_POSITION]);

uint8_t *axis_busy = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + AXIS_BUSY]);
uint8_t *buffer_busy = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + BUFFER_BUSY]);
double *now_motion_aimpos = (double*)(&CassMem[AXIS_BASE + AXIS_SIZE*FB->Axis_num + NOW_MOTION_AIMPOS]);
int32_t *now_motion_direction = (int32_t*)(&CassMem[AXIS_BASE + AXIS_SIZE*FB->Axis_num + NOW_MOTION_DIRECTION]);
float *blending_v = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE*FB->Axis_num + BLENDING_V]);
float *now_motion_vel = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + NOW_MOTION_VEL]);
uint8_t *buffered_without_blending = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + BUFFERED_WITHOUT_BLENDING]);
uint8_t *run_next = (uint8_t*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + RUN_NEXT]);
short int *mode = (short int*)(&CassMem[DRIVER_BASE + DRIVER_SIZE * FB->Axis_num + DRIVER_MODES_DISPLAY]);

float *pulse_ratio = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE*FB->Axis_num + PULSE_RATIO]);
float *angle_ratio = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE*FB->Axis_num + ANGLE_RATIO]);

float *velFactor = (float *)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + VEL_FACTOR]);
float *accFactor = (float *)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + ACC_FACTOR]);
float *jerkFactor = (float *)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + JERK_FACTOR]);
float *maxvel = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + MAXVELOCITY]);
float *maxacc = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + MAXACCELERATION]);
float *maxdec = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + MAXDECELERATION]);
float *maxjerk = (float*)(&CassMem[AXIS_BASE + AXIS_SIZE * FB->Axis_num + MAXJERK]);

double aim_position,tt;
double deviation_pos,deviation_t,deviation_s;
//deviation_s，在最后确定最大速度的S曲线时，计算完成运动后允许的与实际目标位置的偏差，实际运动时会在最后一个周期补偿，强行到位

deviation_s = 0.001;// 100.0;  修改 使用0.1测试没有问题，为了避免发生没有测试到的可能，保险起见，增大到0.2


if((*state == MC_Errorstop || *state == MC_Disabled || *state == MC_Stopping) && (FB->run_flag || FB->exe || FB->run))
{

	FB->CommandAborted = true;
    FB->exe = false;
    FB->run = false;
	FB->run_flag = false;
	FB->buffer = false;
	FB->buffer_run = false;
	FB->reverse = false; //4.13.12.1修改：增加语句
    FB->Active = false;
}


/**当前模块正在执行时,buffer区存在缓存的模块,执行一次计算*/
if(FB->run_flag && *buffer_busy == 1 && !FB->buffer_run)
{
    /**非Buffered_Without_Blending模式下*/
    if(*buffered_without_blending == 0)
    {
        /**当前处于匀速或减速状态*/
        if(FB->move_state == 2 || FB->move_state == 3)
        {
			//修改：原代码：if(*blending_v > *now_velocity - minv)          /**混承速度 > 当前速度*/
            if(*blending_v > fabs(*now_velocity) - minv)          /**混承速度 > 当前速度*/
            {
            	if(!FB->run_mode)		//T
            	{
	            	FB->mode = BLENDING_EQU_ACC;
	               // 修改 原代码：FB->now_vel = *now_velocity;  计算过程的速度FB->now_vel应该为正值，不表示方向；*now_velocity具有正负号，可以表示方向
                    FB->now_vel = fabs(*now_velocity);
	                FB->t5 = ((*blending_v) - FB->now_vel)/FB->acc;
	                FB->s1_ = FB->now_vel*FB->t5 + FB->acc*FB->t5*FB->t5/2;
	                FB->t2_ = 0;
	                FB->t3_ = FB->t_all - FB->t_now;
	                if(FB->t3_ > FB->t3)
	                {
	                    FB->t2_ = FB->t3_ - FB->t3;
	                    FB->t3_ = FB->t3;
	                }
	                FB->s_ = FB->now_vel*FB->t2_ + FB->dec*FB->t3_*FB->t3_/2;
	                FB->t2 -= FB->t2_;
	                FB->t3 -= FB->t3_;
	                FB->t4 = (FB->s_ - FB->s1_)/(FB->now_vel);
	                if(FB->t4 < 0)
	                {
	                    FB->t5 = (sqrt(FB->now_vel * FB->now_vel + 2*FB->acc*FB->s_) - FB->now_vel)/FB->acc;
	                    FB->t4 = 0;
	                    *blending_v = FB->now_vel + FB->t5*FB->acc;
	                }
	                FB->t_all = FB->t1 + FB->t2 + FB->t3 + FB->t4 + FB->t5;
	            }
	            else			//S
				{
					FB->mode = BLENDING_EQU_ACC;
	                // 修改 原代码：FB->now_vel = *now_velocity;  计算过程的速度FB->now_vel应该为正值，不表示方向；*now_velocity具有正负号，可以表示方向
					FB->now_vel = fabs(*now_velocity);
					tt = FB->t_now - FB->t1 - FB->t2 - FB->t3;//第一次修改  原代码：tt = FB->t_all - FB->t1 - FB->t2 - FB->t3;
					if(tt <= FB->t4)
					{
						FB->now_a = 0;
						FB->s_ = FB->s_all - FB->state4_s + FB->vmax*(FB->t4 - tt);
					}
					else if(tt <= FB->t4 + FB->t5)
					{
						FB->now_a = FB->jerk*(tt - FB->t4);
				 		FB->s_ = FB->s_all - FB->state4_s - FB->vmax*(tt - FB->t4) - FB->jerk*(tt - FB->t4)*(tt - FB->t4)*(tt - FB->t4)/6;
					}
					else if(tt <= FB->t4 + FB->t5 + FB->t6)
					{
						FB->now_a = FB->jerk*FB->t5;
						FB->s_ = FB->s_all - FB->state6_s + (FB->jerk*FB->t7*FB->t7)*(FB->t4 + FB->t5 + FB->t6 - tt)/2 + FB->jerk*FB->t7*(FB->t4 + FB->t5 + FB->t6 - tt)*(FB->t4 + FB->t5 + FB->t6 - tt)/2;
					}
					else
					{
						FB->now_a = FB->jerk*(FB->t4 + 2*FB->t5 - tt);
						FB->s_ = FB->jerk*(FB->t4 + FB->t5 + FB->t6 + FB->t7 - tt)*(FB->t4 + FB->t5 + FB->t6 + FB->t7 - tt)*(FB->t4 + FB->t5 + FB->t6 + FB->t7 - tt)/6;
					}

					if(FB->now_a != 0)
					{
						FB->t5 = FB->now_a/FB->jerk;
					}
					else
					{
						FB->t5 = 0;
					}

					FB->blending_start_t = FB->t_now;//修改 原代码：FB->blending_start_t = FB->t_now - 1;
					FB->blending_start_s = FB->s_all - FB->s_;
					FB->blending_equal_vel = FB->now_vel - FB->now_a*FB->t5 + FB->jerk*FB->t5*FB->t5/2;

					FB->s1_ = FB->now_vel*FB->t5 - FB->now_a*FB->t5*FB->t5/2 + FB->jerk*FB->t5*FB->t5*FB->t5/6;

					FB->state5_s = FB->blending_start_s + FB->s1_;


					FB->t7 = FB->acc/FB->jerk;
					FB->t8 = (*blending_v - FB->blending_equal_vel)/FB->acc - FB->t7;
					if(FB->t8 < 0)
					{
						FB->t7 = sqrt((*blending_v - FB->blending_equal_vel)/FB->jerk);
						FB->t8 = 0;
					}
					FB->t9 = FB->t7;
					FB->s2_ = FB->blending_equal_vel*(2*FB->t7 + FB->t8) + FB->jerk*FB->t7*FB->t7*(FB->t7 + FB->t8)/2 + FB->jerk*FB->t7*(FB->t7 + FB->t8)*(FB->t7 + FB->t8)/2;

					FB->t6 = (FB->s_ - FB->s1_ - FB->s2_)/FB->blending_equal_vel;
					if(FB->t6 < 0)
					{
						FB->t6 = 0;
						if(FB->s_ <= FB->s1_)
						{
							FB->s_ = FB->s1_;
							FB->s2_ = 0;
							FB->t7 = 0;
							FB->t8 = 0;
							FB->t9 = 0;
							*blending_v = FB->blending_equal_vel;
						}
						else
						{
							FB->high = *blending_v;
							FB->low = FB->blending_equal_vel;
							FB->t7 = FB->acc/FB->jerk;
							FB->t8 = (*blending_v - FB->blending_equal_vel)/FB->acc - FB->t7;
							if(FB->t8 < 0)
							{
								FB->t7 = sqrt((*blending_v - FB->blending_equal_vel)/FB->jerk);
								FB->t8 = 0;
							}
							FB->t9 = FB->t7;
							FB->s2_ = FB->blending_equal_vel*(2*FB->t7 + FB->t8) + FB->jerk*FB->t7*FB->t7*(FB->t7 + FB->t8)/2 + FB->jerk*FB->t7*(FB->t7 + FB->t8)*(FB->t7 + FB->t8)/2;

							if(deviation_s < *blending_v)
							{
								deviation_s = *blending_v;
							}

							while(FB->s1_ + FB->s2_ < FB->s_ - deviation_s || FB->s1_ + FB->s2_ > FB->s_)
			   				{
			   					if(FB->s1_ + FB->s2_ > FB->s_)
								{
									FB->high = *blending_v;
									*blending_v = (FB->high + FB->low)/2;
								}
								else
								{
									FB->low = *blending_v;
									*blending_v = (FB->high + FB->low)/2;
								}

								FB->t7 = FB->acc/FB->jerk;
								FB->t8 = (*blending_v - FB->blending_equal_vel)/FB->acc - FB->t7;
								if(FB->t8 < 0)
								{
									FB->t7 = sqrt((*blending_v - FB->blending_equal_vel)/FB->jerk);
									FB->t8 = 0;
								}
								FB->t9 = FB->t7;
								FB->s2_ = FB->blending_equal_vel*(2*FB->t7 + FB->t8) + FB->jerk*FB->t7*FB->t7*(FB->t7 + FB->t8)/2 + FB->jerk*FB->t7*(FB->t7 + FB->t8)*(FB->t7 + FB->t8)/2;

							}

						}
					}

					FB->state6_s = FB->state5_s + FB->t6*FB->blending_equal_vel;
					FB->state7_s = FB->state6_s + FB->blending_equal_vel*FB->t7 + FB->jerk*FB->t7*FB->t7*FB->t7/6;
					FB->state8_s = FB->state7_s + FB->jerk*FB->t7*FB->t8*(FB->t7 + FB->t8)/2 + FB->blending_equal_vel*FB->t8;

					FB->t_all = FB->blending_start_t + FB->t5 + FB->t6 + FB->t7 + FB->t8 + FB->t9;


				}

            }
            else                                       /**混承速度 <= 当前速度*/
            {
            	if(!FB->run_mode)
				{
					FB->mode = BLENDING_EQU_DEC;
	                // 修改 原代码：FB->now_vel = *now_velocity;  计算过程的速度FB->now_vel应该为正值，不表示方向；*now_velocity具有正负号，可以表示方向
					FB->now_vel = fabs(*now_velocity);
	                FB->t5 = (FB->now_vel - (*blending_v))/FB->dec;
	                FB->s1_ = FB->now_vel*FB->t5 - FB->dec*FB->t5*FB->t5/2;
	                FB->t2_ = 0;
	                FB->t3_ = FB->t_all - FB->t_now;
	                if(FB->t3_ > FB->t3)
	                {
	                    FB->t2_ = FB->t3_ - FB->t3;
	                    FB->t3_ = FB->t3;
	                }
	                FB->s_ = FB->now_vel*FB->t2_ + FB->dec*FB->t3_*FB->t3_/2;
	                FB->t2 -= FB->t2_;
	                FB->t3 -= FB->t3_;
	                FB->t4 = (FB->s_ - FB->s1_)/FB->now_vel;
	                if(FB->t4 < 0)
	                {
	                    FB->t5 = (sqrt(FB->now_vel * FB->now_vel - 2*FB->dec*FB->s_) + FB->now_vel)/FB->dec;
	                    FB->t4 = 0;
	                    *blending_v = FB->now_vel - FB->t5*FB->dec;
	                }
	                FB->t_all = FB->t1 + FB->t2 + FB->t3 + FB->t4 + FB->t5;
				}
				else
				{
					FB->mode = BLENDING_EQU_DEC;
					// 修改 原代码：FB->now_vel = *now_velocity;  计算过程的速度FB->now_vel应该为正值，不表示方向；*now_velocity具有正负号，可以表示方向
					FB->now_vel = fabs(*now_velocity);
					tt = FB->t_now - FB->t1 - FB->t2 - FB->t3 ;//第一次修改  原代码：tt = FB->t_all - FB->t1 - FB->t2 - FB->t3;
					if(tt <= FB->t4)
					{
						FB->now_a = 0;
						FB->s_ = FB->s_all - FB->state4_s + FB->vmax*(FB->t4 - tt);
					}
					else if(tt <= FB->t4 + FB->t5)
					{
						FB->now_a = FB->jerk*(tt - FB->t4);
				 		FB->s_ = FB->s_all - FB->state4_s - FB->vmax*(tt - FB->t4) - FB->jerk*(tt - FB->t4)*(tt - FB->t4)*(tt - FB->t4)/6;
					}
					else if(tt <= FB->t4 + FB->t5 + FB->t6)
					{
						FB->now_a = FB->jerk*FB->t5;
						FB->s_ = FB->s_all - FB->state6_s + (FB->jerk*FB->t7*FB->t7)*(FB->t4 + FB->t5 + FB->t6 - tt)/2 + FB->jerk*FB->t7*(FB->t4 + FB->t5 + FB->t6 - tt)*(FB->t4 + FB->t5 + FB->t6 - tt)/2;
					}
					else
					{
						FB->now_a = FB->jerk*(FB->t4 + 2*FB->t5 - tt);
						FB->s_ = FB->jerk*(FB->t4 + FB->t5 + FB->t6 + FB->t7 - tt)*(FB->t4 + FB->t5 + FB->t6 + FB->t7 - tt)*(FB->t4 + FB->t5 + FB->t6 + FB->t7 - tt)/6;
					}

					if(FB->now_a != 0)
					{
						FB->t5 = FB->now_a/FB->jerk;
					}
					else
					{
						FB->t5 = 0;
					}

					FB->blending_start_t = FB->t_now;//修改 原代码：FB->blending_start_t = FB->t_now - 1;
					FB->blending_start_s = FB->s_all - FB->s_;
					FB->blending_equal_vel = FB->now_vel - FB->now_a*FB->t5 + FB->jerk*FB->t5*FB->t5/2;

					FB->s1_ = FB->now_vel*FB->t5 - FB->now_a*FB->t5*FB->t5/2 + FB->jerk*FB->t5*FB->t5*FB->t5/6;

					FB->state5_s = FB->blending_start_s + FB->s1_;


					FB->t7 = FB->dec/FB->jerk;
					FB->t8 = (FB->blending_equal_vel - *blending_v)/FB->dec - FB->t7;
					if(FB->t8 < 0)
					{
						FB->t7 = sqrt((FB->blending_equal_vel - *blending_v)/FB->jerk);
						FB->t8 = 0;
					}
					FB->t9 = FB->t7;
					FB->s2_ = FB->blending_equal_vel*(2*FB->t7 + FB->t8) - FB->jerk*FB->t7*FB->t7*(FB->t7 + FB->t8)/2 - FB->jerk*FB->t7*(FB->t7 + FB->t8)*(FB->t7 + FB->t8)/2;

					FB->t6 = (FB->s_ - FB->s1_ - FB->s2_)/FB->blending_equal_vel;
					if(FB->t6 < 0)
					{
						FB->t6 = 0;
						if(FB->s_ <= FB->s1_)
						{
							FB->s_ = FB->s1_;
							FB->s2_ = 0;
							FB->t7 = 0;
							FB->t8 = 0;
							FB->t9 = 0;
							*blending_v = FB->blending_equal_vel;
						}
						else
						{
							FB->low = *blending_v;
							FB->high = FB->blending_equal_vel;
							FB->t7 = FB->dec/FB->jerk;
							FB->t8 = (FB->blending_equal_vel - *blending_v)/FB->acc - FB->t7;
							if(FB->t8 < 0)
							{
								FB->t7 = sqrt((FB->blending_equal_vel - *blending_v)/FB->jerk);
								FB->t8 = 0;
							}
							FB->t9 = FB->t7;
							FB->s2_ = FB->blending_equal_vel*(2*FB->t7 + FB->t8) - FB->jerk*FB->t7*FB->t7*(FB->t7 + FB->t8)/2 - FB->jerk*FB->t7*(FB->t7 + FB->t8)*(FB->t7 + FB->t8)/2;

							if(deviation_s < *blending_v)
							{
								deviation_s = *blending_v;
							}

							while(FB->s1_ + FB->s2_ < FB->s_ - deviation_s || FB->s1_ + FB->s2_ > FB->s_)
			   				{
			   					if(FB->s1_ + FB->s2_ > FB->s_)
								{
									FB->low = *blending_v;
									*blending_v = (FB->high + FB->low)/2;
								}
								else
								{
									FB->high = *blending_v;
									*blending_v = (FB->high + FB->low)/2;
								}

								FB->t7 = FB->dec/FB->jerk;
								FB->t8 = (FB->blending_equal_vel - *blending_v)/FB->acc - FB->t7;
								if(FB->t8 < 0)
								{
									FB->t7 = sqrt((FB->blending_equal_vel - *blending_v)/FB->jerk);
									FB->t8 = 0;
								}
								FB->t9 = FB->t7;
								FB->s2_ = FB->blending_equal_vel*(2*FB->t7 + FB->t8) - FB->jerk*FB->t7*FB->t7*(FB->t7 + FB->t8)/2 - FB->jerk*FB->t7*(FB->t7 + FB->t8)*(FB->t7 + FB->t8)/2;

							}

						}
					}

					FB->state6_s = FB->state5_s + FB->t6*FB->blending_equal_vel;
					FB->state7_s = FB->state6_s + FB->blending_equal_vel*FB->t7 - FB->jerk*FB->t7*FB->t7*FB->t7/6;
					FB->state8_s = FB->state7_s + FB->blending_equal_vel*FB->t8 - FB->jerk*FB->t7*FB->t8*(FB->t7 + FB->t8)/2;

					FB->t_all = FB->blending_start_t + FB->t5 + FB->t6 + FB->t7 + FB->t8 + FB->t9;

				}

            }
            FB->buffer_run = true;
        }
        else if(FB->move_state == 4)
        {
        	FB->move_state = 0;
            FB->run_flag = false;
            *axis_busy = 0;
            FB->Active = false;
            FB->Done = true;
            FB->CommandAborted = false;
            FB->buffer_run = true;
		}
    }
    else
    {
        FB->buffer_run = true;
    }


}

/**上跳沿触发，run_flag ==false 才进来，防止功能块重复启动*/
if(FB->run_flag == false && FB->Execute && (!FB->execute_before))
{
	if(FB->Axis_num >= AXIS_MAXNUM || FB->Velocity <= minv || FB->Acceleration <= minv || FB->Deceleration <= minv || FB->Velocity > *maxvel || FB->Acceleration > *maxacc || FB->Deceleration > *maxdec || FB->Jerk > *maxjerk)
	{
		FB->Error = true;
		FB->ErrorID = ParameterError;
	}
	else
    {
        if(*state != MC_Standstill && *state != MC_Discrete_Motion && *state != MC_Continuous_Motion)
        {
            FB->Error = true;
			FB->ErrorID = StateError;
        }
        else
        {
            FB->Error = false;
            FB->ErrorID = NoError;
        }
    }

    if(!FB->Error)
    {
        FB->vel = *velFactor * FB->Velocity/1000.0;
        FB->acc = *accFactor * FB->Acceleration/1000000.0;
        FB->dec = *accFactor * FB->Deceleration/1000000.0;
        FB->jerk =*jerkFactor * FB->Jerk/1000000000.0;
        FB->pos = FB->Position - *relative_position;
        FB->exe = true;
        FB->buffer = false;
        FB->run = false;
        FB->run_flag = false;
        FB->reverse = false;//4.13.12.1修改：增加语句
    }

}

if(FB->exe)
{
    if(FB->BufferMode == Aborting)  //当前功能块以中止模式启动，打断前一个功能块，标准p112，
    {
        FB->run = true;
    }
    //*buffer_busy 为 1表示存在buffed的功能块
    else if(FB->BufferMode == Buffered)  //仅缓冲，非混成，以初速度0启动
    {
        /**进入缓冲区*/
        if(*buffer_busy == 0)
        {
            *buffered_without_blending = 1;
            FB->buffer = true;
            *buffer_busy = 1;
        }
        /**等前一个任务执行完成*/
        if(FB->buffer && *axis_busy == 0 && *run_next == 0)
        {
            FB->buffer = false;
            *buffer_busy = 0;
            FB->run = true;
        }
    }

    else if(FB->BufferMode == Blendinglow)
    {
        /**进入缓冲区*/
        if(*buffer_busy == 0)
        {
            if(*now_motion_vel > FB->vel)
            {
                *blending_v = FB->vel;
            }
            else
            {
                *blending_v = *now_motion_vel;
            }
            FB->buffer = true;
            *buffer_busy = 1;

        }
        /**等前一个任务执行完成*/
        if(FB->buffer && *axis_busy == 0 )//&& *run_next == 0)//修改判断条件，提前一个周期运行
        {

            FB->buffer = false;
            *buffer_busy = 0;
            FB->run = true;
        }
    }

    else if(FB->BufferMode == BlendingPrevious)
    {
        /**进入缓冲区*/
        if(*buffer_busy == 0)
        {
            *blending_v = *now_motion_vel;
            FB->buffer = true;
            *buffer_busy = 1;

        }
        /**等前一个任务执行完成*/
        if(FB->buffer && *axis_busy == 0 )//&& *run_next == 0)
        {
            FB->buffer = false;
            *buffer_busy = 0;
            FB->run = true;
        }
    }

    else if(FB->BufferMode == BlendingNext)
    {
        /**进入缓冲区*/
        if(*buffer_busy == 0 && !FB->buffer)
        {
            *blending_v = FB->vel;
            FB->buffer = true;
            *buffer_busy = 1;
        }
        /**等前一个任务执行完成*/
        if(FB->buffer && *axis_busy == 0)
        {
            FB->buffer = false;
            *buffer_busy = 0;
            FB->run = true;
        }
    }

    else if(FB->BufferMode == BlendingHigh)
    {
        /**进入缓冲区*/
        if(*buffer_busy == 0 && !FB->buffer)
        {
            if(*now_motion_vel > FB->vel)
            {
                *blending_v = *now_motion_vel;
            }
            else
            {
                *blending_v = FB->vel;
            }
            FB->buffer = true;
            *buffer_busy = 1;
        }
        /**等前一个任务执行完成*/
        if(FB->buffer && *axis_busy == 0 )//&& *run_next == 0)//修改判断条件，提前一个周期运行
        {
            FB->buffer = false;
            *buffer_busy = 0;
            FB->run = true;
        }
    }

    /**前后两个运动方向不同,则不能混承,自动变成Buffered_Without_Blending*/
    if(FB->buffer)
    {
        if((FB->pos >= *now_motion_aimpos && *now_motion_direction < 0) || (FB->pos <= *now_motion_aimpos && *now_motion_direction > 0))
        {
            *buffered_without_blending = 1;
        }
    }


}

/**当前模块进行运动,计算轨迹*/
if(FB->run)  //只做一次
{
    FB->run = false;
    if(*run_numberm == 255)   //当前轴的mc功能块编号
    {
        *run_numberm = 1;
    }
    else
    {
        *run_numberm = *run_numberm + 1;
    }
    FB->run_numberF = *run_numberm;
    *axis_busy = 1;
    FB->exe = false;
    FB->buffer = false;
    *buffered_without_blending = 0;
    if(*mode != Position_Mode)
    {
    	FB->now_position = *now_position;   //*now_position从DriverSync功能块过来
    	*last_target_position = *now_position;
    	*target_position = *last_target_position;
    }
    else
    {
    	FB->now_position = *last_target_position;
//		printf("MoveABS: FB->Axis_num = %d, FB->pos = %lf, FB->now_position=%lf\n",FB->Axis_num, FB->pos,FB->now_position);
    }
    /**计算目标位置相对于当前位置的方向*/
    if(FB->pos >= FB->now_position)
    {
        FB->s = FB->pos - FB->now_position;
        FB->direction = 1;
    }
    else
    {
        FB->s = FB->now_position - FB->pos;
        FB->direction = -1;
    }
    /**计算初速度方向*/
    FB->vs = *now_velocity;

    if(*now_velocity >= minv)
    {
        FB->now_direction = 1;
    }
    else if(*now_velocity <= (-1)*minv)
    {
        FB->vs = (-1)*FB->vs;
        FB->now_direction = -1;
    }
    else
    {
        FB->vs = 0;
        FB->now_direction = FB->direction;
    }

    if(FB->jerk > 0)
    {
    	FB->run_mode = true;   //S型
    }
    else
    {
    	FB->run_mode = false;  //梯形运动
    }

    /**记录下当前运动的信息*/
    *now_motion_aimpos = FB->pos;
    *now_motion_vel = FB->vel;
    *now_motion_direction = FB->direction;

    if(FB->s <= minp)			/**一开始就在目标位置，FB->s为距离*/
    {
        FB->run_flag = false;
        FB->Done = true;
        FB->CommandAborted = false;
        FB->Active = false;
        *axis_busy = 0;
		//printf("MoveABSif(FB->s <= minp): FB->Axis_num = %d, FB->pos = %lf, FB->now_position=%lf\n",FB->Axis_num, FB->pos,FB->now_position);
    }
    else                        /**开始运动*/
    {
        *state = MC_Discrete_Motion;
        if(!FB->run_mode)               /**梯形运动*/
        {
            /**目标方向与当前速度方向不同,先减速至0，同时会产生rs位移，新的s变成rs+s。。 s距离，v速度，t,a,......*/
            if(FB->direction != FB->now_direction)
            {
                FB->reverse = true;
                FB->rvs = FB->vs;
                FB->rt1 = FB->rvs/FB->dec;
                FB->rs = FB->rvs*FB->rt1 - FB->dec*FB->rt1*FB->rt1/2;
                FB->s += FB->rs;
                FB->vs = 0;
            }

            /**若初速度小于最大速度*/
            if(FB->vs < FB->vel - minv)
            {
                FB->mode = ACC_EQU_DEC;
                FB->vmax = FB->vel;
                FB->t1 = (FB->vmax - FB->vs)/FB->acc;
                FB->t3 = FB->vmax/FB->dec;
                FB->s1 = FB->vs*FB->t1 + FB->acc*FB->t1*FB->t1/2 + FB->vmax*FB->t3 - FB->dec*FB->t3*FB->t3/2;
                if(*mode != Position_Mode)
                {
                	FB->t2 = (FB->s - FB->s1)/FB->vmax - deviation;
                }
                else
                {
                	FB->t2 = (FB->s - FB->s1)/FB->vmax;
                }
                if(FB->t2 < 0)
                {
					FB->t2 = 0;
                	FB->t1 = 0;
            		FB->t3 = (FB->vs - FB->vm)/FB->dec;
            		FB->s2 = FB->vs*FB->t3 - FB->dec*FB->t3*FB->t3/2;
            		FB->vmax = FB->vs;
            		if(FB->s <= FB->s2)
            		{
		            	FB->s = FB->s2;
		            }
                	else
                	{
	                	if(*mode != Position_Mode)
		                {
		                	FB->t1 = (sqrt(FB->vs*FB->vs - FB->acc*(FB->vs*FB->vs - 2*FB->dec*FB->s)/(FB->acc + FB->dec)) - FB->vs)/FB->acc - deviation/2;
		                }
		                else
		                {
		                	FB->t1 = (sqrt(FB->vs*FB->vs - FB->acc*(FB->vs*FB->vs - 2*FB->dec*FB->s)/(FB->acc + FB->dec)) - FB->vs)/FB->acc;
		                }
	                    if(FB->t1 < 0)
	                    {
	                    	FB->t1 = 0;
	                    }
	                    FB->t3 = (FB->vs + FB->acc*FB->t1)/FB->dec;
	                    FB->vmax = FB->vs + FB->acc*FB->t1;
	                }

                }
                FB->state1_s = FB->vs*FB->t1 + FB->acc*FB->t1*FB->t1/2;
                FB->state2_s = FB->vmax*FB->t2;
                FB->s_all = FB->state1_s + FB->state2_s + FB->dec*FB->t3*FB->t3/2;
                FB->t_all = FB->t1 + FB->t2 + FB->t3;
            }

            /**若初速度大于等于最大速度*/
            else //if(FB->vs >= FB->vel - minv)
            {
                FB->mode = DEC_EQU_DEC;
                FB->vmax = FB->vel;
                FB->t1 = (FB->vs - FB->vmax)/FB->dec;
				//修改 (FB->vs - FB->vmax)为负数时，t1 < 0
				if(FB->t1 < 0.01)
				{
					FB->t1 = 0;
				}
                FB->t3 = FB->vmax/FB->dec;
                FB->s1 = FB->vs*FB->t1 - FB->dec*FB->t1*FB->t1/2 + FB->vmax*FB->t3 - FB->dec*FB->t3*FB->t3/2;
                if(*mode != Position_Mode)
                {
                	FB->t2 = (FB->s - FB->s1)/FB->vmax - deviation;
                }
                else
                {
                	FB->t2 = (FB->s - FB->s1)/FB->vmax;
                }
                if(FB->t2 < 0)
                {
                    FB->t2 = 0;
                }
                FB->state1_s = FB->vs*FB->t1 - FB->dec*FB->t1*FB->t1/2;
                FB->state2_s = FB->vmax*FB->t2;
                FB->s_all = FB->state1_s + FB->state2_s + FB->dec*FB->t3*FB->t3/2;
                FB->t_all = FB->t1 + FB->t2 + FB->t3;
            }
        }
        else				//S型曲线
        {
        	/**目标方向与当前速度方向不同,先减速至0*/
            if(FB->direction != FB->now_direction)
            {
                FB->reverse = true;
                FB->rvs = FB->vs;
                FB->rt1 = FB->dec/FB->jerk;
                FB->rt2 = FB->rvs/FB->dec - FB->rt1;
                if(FB->rt2 < 0)
                {
                	FB->rt2 = 0;
                	FB->rt1 = sqrt(FB->rvs/FB->jerk);
                }
                FB->rt3 = FB->rt1;
                FB->rs = FB->rvs*(2*FB->rt1 + FB->rt2) - FB->rt1*FB->jerk*(FB->rt1+FB->rt2)*(FB->rt1+FB->rt2)/2 - FB->rt1*FB->rt1*FB->jerk*(FB->rt1 + FB->rt2)/2;
                FB->s += FB->rs;
                FB->vs = 0;

                FB->stater1_s = FB->rvs*FB->rt1 - FB->jerk*FB->rt1*FB->rt1*FB->rt1/6;
			 	FB->stater2_s = FB->stater1_s + FB->rvs*FB->rt2 - FB->jerk*FB->rt1*FB->rt1*FB->rt2/2 - FB->jerk*FB->rt1*FB->rt2*FB->rt2/2;

            }

            /**若初速度小于最大速度*/
            if(FB->vs < FB->vel - 1)//速度差超过1脉冲，才会有加速的必要
            {
                FB->mode = ACC_EQU_DEC;
                FB->vmax = FB->vel;
                FB->vm = 0;
                FB->t1 = FB->acc/FB->jerk;
				FB->t2 = (FB->vmax - FB->vs)/FB->acc - FB->t1;
				if(FB->t2 < 0)
				{
					FB->t1 = sqrt((FB->vmax - FB->vs)/FB->jerk);
					FB->t2 = 0;
				}
				FB->t3 = FB->t1;
				FB->s1 = FB->vs*(2*FB->t1 + FB->t2) + FB->jerk*FB->t1*FB->t1*(FB->t1 + FB->t2)/2 + FB->jerk*FB->t1*(FB->t1 + FB->t2)*(FB->t1 + FB->t2)/2;

				FB->t5 = FB->dec/FB->jerk;
				FB->t6 = (FB->vmax - FB->vm)/FB->dec - FB->t5;
				if(FB->t6 < 0)
				{
					FB->t5 = sqrt((FB->vmax - FB->vm)/FB->jerk);
					FB->t6 = 0;
				}
				FB->t7 = FB->t5;
				FB->s2 = FB->vmax*(2*FB->t5 + FB->t6) - FB->jerk*FB->t5*FB->t5*(FB->t5 + FB->t6)/2 - FB->jerk*FB->t5*(FB->t5 + FB->t6)*(FB->t5 + FB->t6)/2;
   				FB->t4 = (FB->s - FB->s1 - FB->s2)/FB->vmax;
                if(FB->t4 < 0)				//达不到最大速度
				{
					FB->t4 = 0;
					FB->vmax = FB->vs;
					FB->t5 = FB->dec/FB->jerk;
					FB->t6 = (FB->vmax - FB->vm)/FB->dec - FB->t5;
					if(FB->t6 < 0)
					{
						FB->t5 = sqrt((FB->vmax - FB->vm)/FB->jerk);
						FB->t6 = 0;
					}
					FB->t7 = FB->t5;
					FB->s2 = FB->vmax*(2*FB->t5 + FB->t6) - FB->jerk*FB->t5*FB->t5*(FB->t5 + FB->t6)/2 - FB->jerk*FB->t5*(FB->t5 + FB->t6)*(FB->t5 + FB->t6)/2;
					if(FB->s > FB->s2)			//距离合理
					{
						FB->vmax = FB->vel;
						FB->low = FB->vs;
						FB->high = FB->vmax;
						FB->vmax = (FB->low + FB->high)/2;

						FB->t1 = FB->acc/FB->jerk;
						FB->t2 = (FB->vmax - FB->vs)/FB->acc - FB->t1;
						if(FB->t2 < 0)
						{
							FB->t1 = sqrt((FB->vmax - FB->vs)/FB->jerk);
							FB->t2 = 0;
						}
						FB->t3 = FB->t1;
						FB->s1 = FB->vs*(2*FB->t1 + FB->t2) + FB->jerk*FB->t1*FB->t1*(FB->t1 + FB->t2)/2 + FB->jerk*FB->t1*(FB->t1 + FB->t2)*(FB->t1 + FB->t2)/2;

						FB->t5 = FB->dec/FB->jerk;
						FB->t6 = (FB->vmax - FB->vm)/FB->dec - FB->t5;
						if(FB->t6 < 0)
						{
							FB->t5 = sqrt((FB->vmax - FB->vm)/FB->jerk);
							FB->t6 = 0;
						}
						FB->t7 = FB->t5;
						FB->s2 = FB->vmax*(2*FB->t5 + FB->t6) - FB->jerk*FB->t5*FB->t5*(FB->t5 + FB->t6)/2 - FB->jerk*FB->t5*(FB->t5 + FB->t6)*(FB->t5 + FB->t6)/2;
                        int count_flag=0;
                        while(FB->s1 + FB->s2 < FB->s - deviation_s || FB->s1 + FB->s2 > FB->s  + deviation_s)
		   				{
							count_flag++;
							if(count_flag > 30)//2的30次方约为1E9万,速度应该不可能超过5E8脉冲每毫秒
							{
								break;
							}
		   					if(FB->s1 + FB->s2 > FB->s)
							{
								FB->high = FB->vmax;
								FB->vmax = (FB->high + FB->low)/2;
							}
							else
							{
								FB->low = FB->vmax;
								FB->vmax = (FB->high + FB->low)/2;
							}
							FB->t1 = FB->acc/FB->jerk;
							FB->t2 = (FB->vmax - FB->vs)/FB->acc - FB->t1;
							if(FB->t2 < 0)
							{
								FB->t1 = sqrt((FB->vmax - FB->vs)/FB->jerk);
								FB->t2 = 0;
							}
							FB->t3 = FB->t1;
							FB->s1 = FB->vs*(2*FB->t1 + FB->t2) + FB->jerk*FB->t1*FB->t1*(FB->t1 + FB->t2)/2 + FB->jerk*FB->t1*(FB->t1 + FB->t2)*(FB->t1 + FB->t2)/2;

							FB->t5 = FB->dec/FB->jerk;
							FB->t6 = (FB->vmax - FB->vm)/FB->dec - FB->t5;
							if(FB->t6 < 0)
							{
								FB->t5 = sqrt((FB->vmax - FB->vm)/FB->jerk);
								FB->t6 = 0;
							}
							FB->t7 = FB->t5;
							FB->s2 = FB->vmax*(2*FB->t5 + FB->t6) - FB->jerk*FB->t5*FB->t5*(FB->t5 + FB->t6)/2 - FB->jerk*FB->t5*(FB->t5 + FB->t6)*(FB->t5 + FB->t6)/2;
				   		}
				   		FB->s2 = FB->s - FB->s1; //此句可能会造成最后一个位置突变，因为FB->s_all = FB->s1 + FB->s2 + FB->vmax*FB->t4;
					}			//end FB->s > FB->s2,计算完t,s1,s2
					else		//距离不合理，只有减速
					{
						FB->t1 = 0;
						FB->t2 = 0;
						FB->t3 = 0;
						FB->s1 = 0;
						FB->vmax = FB->vs;
						FB->t5 = FB->dec/FB->jerk;
						FB->t6 = (FB->vmax - FB->vm)/FB->dec - FB->t5;
						if(FB->t6 < 0)
						{
							FB->t5 = sqrt((FB->vmax - FB->vm)/FB->jerk);
							FB->t6 = 0;
						}
						FB->t7 = FB->t5;
						FB->s2 = FB->vmax*(2*FB->t5 + FB->t6) - FB->jerk*FB->t5*FB->t5*(FB->t5 + FB->t6)/2 - FB->jerk*FB->t5*(FB->t5 + FB->t6)*(FB->t5 + FB->t6)/2;
					}
				} 		//end FB->t4 < 0

				FB->state1_s = FB->vs*FB->t1 + FB->jerk*FB->t1*FB->t1*FB->t1/6;
				FB->state2_s = FB->state1_s + (FB->jerk*FB->t1*FB->t1/2 + FB->vs)*FB->t2 + FB->jerk*FB->t1*FB->t2*FB->t2/2;
				FB->state3_s = FB->state2_s + 5*FB->jerk*FB->t1*FB->t1*FB->t1/6 + FB->vs*FB->t1 + FB->jerk*FB->t1*FB->t1*FB->t2;
			 	FB->state4_s = FB->state3_s + FB->vmax*FB->t4;
			 	FB->state5_s = FB->state4_s + FB->vmax*FB->t5 - FB->jerk*FB->t5*FB->t5*FB->t5/6;
			 	FB->state6_s = FB->state5_s + FB->vmax*FB->t6 - FB->jerk*FB->t5*FB->t5*FB->t6/2 - FB->jerk*FB->t5*FB->t6*FB->t6/2;
			 	FB->s_all = FB->s1 + FB->s2 + FB->vmax*FB->t4;
                FB->t_all = FB->t1 + FB->t2 + FB->t3 + FB->t4 + FB->t5 + FB->t6 + FB->t7;
            }		//end FB->vs < FB->vel - minv

            /**若初速度大于等于最大速度*/
            else //if(FB->vs >= FB->vel - 1)
            {
                FB->mode = DEC_EQU_DEC;
                FB->vmax = FB->vel;
				FB->vm = 0;

				FB->t1 = FB->dec/FB->jerk;
				FB->t2 = (FB->vs - FB->vm)/FB->dec - FB->t1;
				if(FB->t2 < 0)
				{
					FB->t1 = sqrt((FB->vs - FB->vm)/FB->jerk);
					FB->t2 = 0;
				}
				FB->t3 = FB->t1;
				FB->s1 = FB->vs*(2*FB->t1 + FB->t2) - FB->jerk*FB->t1*FB->t1*(FB->t1 + FB->t2)/2 - FB->jerk*FB->t1*(FB->t1 + FB->t2)*(FB->t1 + FB->t2)/2;
				if(FB->s > FB->s1)			//距离合理
				{
					FB->t1 = FB->dec/FB->jerk;
					FB->t2 = (FB->vs - FB->vmax)/FB->dec - FB->t1;
					if((FB->vs - FB->vmax)<1)//速度相差 1 脉冲为允许误差 计算结果可能为负值也可能为正
					{
					//修改 vs=vmax => t1.t2.t3.s1=0
                        FB->t2 = 0;
                        FB->t1 = 0;
					}
					else if(FB->t2 < 0)
					{
						FB->t1 = sqrt((FB->vs - FB->vmax)/FB->jerk);
						FB->t2 = 0;
					}
					FB->t3 = FB->t1;
					FB->s1 = FB->vs*(2*FB->t1 + FB->t2) - FB->jerk*FB->t1*FB->t1*(FB->t1 + FB->t2)/2 - FB->jerk*FB->t1*(FB->t1 + FB->t2)*(FB->t1 + FB->t2)/2;

					FB->t5 = FB->dec/FB->jerk;
					FB->t6 = (FB->vmax - FB->vm)/FB->dec - FB->t5;
					if(FB->t6 < 0)
					{
						FB->t5 = sqrt((FB->vmax - FB->vm)/FB->jerk);
						FB->t6 = 0;
					}
					FB->t7 = FB->t5;
					//修改 原代码：FB->s2 = FB->vs*(2*FB->t5 + FB->t6) - FB->jerk*FB->t5*FB->t5*(FB->t5 + FB->t6)/2 - FB->jerk*FB->t5*(FB->t5 + FB->t6)*(FB->t5 + FB->t6)/2;
					FB->s2 = FB->vmax*(2*FB->t5 + FB->t6) - FB->jerk*FB->t5*FB->t5*(FB->t5 + FB->t6)/2 - FB->jerk*FB->t5*(FB->t5 + FB->t6)*(FB->t5 + FB->t6)/2;

					FB->t4 = (FB->s - FB->s1 - FB->s2)/FB->vmax;
					if(FB->t4 < 0)
					{
						FB->t4 = 0;
					}

				}
				else
				{
					FB->t5 = FB->t1;
					FB->t6 = FB->t2;
					FB->t7 = FB->t3;
					FB->s2 = FB->s1;
					FB->vmax = FB->vs;
					FB->t1 = FB->t2 = FB->t3 = FB->t4 = 0;
					FB->s1 = 0;
				}

				FB->state1_s = FB->vs*FB->t1 - FB->jerk*FB->t1*FB->t1*FB->t1/6;
			 	FB->state2_s = FB->state1_s + FB->vs*FB->t2 - FB->jerk*FB->t1*FB->t1*FB->t2/2 - FB->jerk*FB->t1*FB->t2*FB->t2/2;
			 	FB->state3_s = FB->state2_s + FB->vs*FB->t1 - FB->jerk*FB->t1*FB->t1*FB->t1/3 - FB->jerk*FB->t1*FB->t1*(2*FB->t2 + FB->t1)/2;
				FB->state4_s = FB->state3_s + FB->vmax*FB->t4;
				FB->state5_s = FB->state4_s + FB->vmax*FB->t5 - FB->jerk*FB->t5*FB->t5*FB->t5/6;
				FB->state6_s = FB->state5_s + FB->vmax*FB->t6 - FB->jerk*FB->t5*FB->t5*FB->t6/2 - FB->jerk*FB->t5*FB->t6*FB->t6/2;

				FB->s_all = FB->s1 + FB->s2 + FB->vmax*FB->t4;
                FB->t_all = FB->t1 + FB->t2 + FB->t3 + FB->t4 + FB->t5 + FB->t6 + FB->t7;
            }


        }		//end FB->run_mode
        FB->t_now = (float)Task->taskPeriod / 1000;
        FB->run_flag = true;
    }
    FB->j = 0;
    FB->deviation_flag = false;
}

FB->execute_before = FB->Execute;

/**每个周期执行一次*/
if(FB->run_flag)
{
    if(*run_numberm != FB->run_numberF)     /**运动被打断*/
    {
        FB->CommandAborted = true;
        FB->run_flag = false;
        FB->run_numberF = 0;
        FB->Active = false;
        FB->Done = false;
        FB->move_state = 0;
        FB->reverse = false;//4.13.12.1修改：增加语句
    }
    else
    {
        FB->Active = true;
        *axis_busy = 1;
        if(!FB->run_mode)           /**梯形曲线*/
        {
            if(FB->reverse)         /**先减速至0*/
            {
                if(FB->t_now >= FB->rt1)  //反向时间到了，目标位置=计算出来反向距离结束点位置
                {
                    *target_position = FB->now_position + FB->now_direction*FB->rs;
                    FB->now_position += FB->now_direction*FB->rs;
                    FB->t_now = 0;
                    FB->reverse = false;
                    FB->move_state = 0;
                }
                else if(FB->t_now < FB->rt1)
                {
                    aim_position = FB->rvs*FB->t_now - FB->dec*FB->t_now*FB->t_now/2;
                    *target_position = FB->now_position + FB->now_direction*aim_position;
                    FB->move_state = 0;
                }
            }
            else
            {
                if(FB->mode == ACC_EQU_DEC)         /**先加速,再匀速,最后减速*/
                {
                    if(*mode != Position_Mode)      //为位置模式，程序不可用
                    {
                        if(FB->t_now <= FB->t1)
                        {
                            aim_position = FB->vs*FB->t_now + FB->acc*FB->t_now*FB->t_now/2;
                            *target_position = FB->now_position + FB->direction*aim_position;
                            FB->move_state = 1;
                        }
                        else if(FB->t_now <= FB->t1 + FB->t2)
                        {
                            aim_position = FB->state1_s + FB->vmax*(FB->t_now - FB->t1);
                            *target_position = FB->now_position + FB->direction*aim_position;
                            FB->move_state = 2;
                            if(!FB->deviation_flag && (FB->t_now - FB->t1) >= deviation_b*FB->t2 &&
                                ((*now_position > *last_target_position && FB->direction == 1) ||
                                (*now_position < *last_target_position && FB->direction == -1)))
                            {
                                FB->deviation_flag = true;
                                deviation_pos = fabs(*now_position - *last_target_position);
                                deviation_t = deviation_pos/FB->vmax;
                                if(deviation_t >= FB->t2 - (FB->t_now - FB->t1))
                                {
                                    deviation_t = FB->t2 - (FB->t_now - FB->t1);
                                }
                                FB->t2 -= deviation_t;
                                FB->t_all -= deviation_t;
                                FB->now_position += deviation_pos*FB->direction;
                                *target_position = FB->now_position + FB->direction*aim_position;
                                *last_target_position = *target_position - FB->direction*FB->vmax;
                                FB->state2_s = FB->vmax*FB->t2;
                            }

                    }
                        else if(FB->t_now < FB->t1 + FB->t2 + FB->t3)
                        {
                            aim_position = FB->state1_s + FB->state2_s + FB->vmax*(FB->t_now - FB->t1 - FB->t2) - FB->dec*(FB->t_now - FB->t1 - FB->t2)*(FB->t_now - FB->t1 - FB->t2)/2;
                            *target_position = FB->now_position + FB->direction*aim_position;
                            FB->move_state = 3;
                        }
                        else
                        {
                            FB->move_state = 4;
                        }

                        if(FB->direction == 1 && FB->move_state >= 3)
                        {
                            if(*now_position >= FB->pos - tiqian_pos || (*now_position - FB->pos_last < 0.5*minp && FB->j == 10))
                            {
                                FB->move_state = 0;
                                *last_target_position = *now_position;
                                *target_position = *last_target_position;
                                console_printf(REVERSE "---01 ACC_EQU_DEC FB->move_state >= 3");

                                *axis_busy = 0;
                                *run_next = 1;
                                FB->run_flag = false;
                                FB->Active = false;
                                FB->Done = true;
                                FB->CommandAborted = false;
                            }
                            else if(*target_position - *last_target_position < special_minv)
                            {
                                FB->move_state = 4;
                                *target_position = *last_target_position + special_minv;
                            }

                        }
                        else if(FB->direction == -1 && FB->move_state >= 3)
                        {
                            if(*now_position <= FB->pos + tiqian_pos || (FB->pos_last - *now_position < 0.5*minp && FB->j == 10))
                            {
                                FB->move_state = 0;
                                *last_target_position = *now_position;
                                *target_position = *last_target_position;
                                console_printf(REVERSE "---02 ACC_EQU_DEC FB->move_state >= 3");
                                *axis_busy = 0;
                                *run_next = 1;
                                FB->run_flag = false;
                                FB->Active = false;
                                FB->Done = true;
                                FB->CommandAborted = false;
                            }
                            else if(*last_target_position - *target_position < special_minv)
                            {
                                FB->move_state = 4;
                                *target_position = *last_target_position - special_minv;
                            }

                        }
                    }
                    else
                    {
                        if(FB->t_now >= FB->t_all)
                        {
                            //*target_position = FB->now_position + FB->direction*FB->s_all;
                            *target_position = FB->pos;
                            //console_printf(REVERSE "1 ACC_EQU_DEC done ,*target_position = %lf,FB->pos = %lf \n " NONE , *target_position, FB->pos) ;
                            if(*buffer_busy == 0)
                            {
                                *now_motion_aimpos = *target_position;//可能会存在减速到0的时候已经超出给定目标位置，所以只能修改目标now_motion_aimpos位置
                            }
                            FB->move_state = 0;
                            FB->run_flag = false;
                            *axis_busy = 0;
                            FB->Active = false;
                            FB->Done = true;
                            FB->CommandAborted = false;
                            *run_next = 1;   //控制下一个周期启动bufferd的功能块
                        }
                        else if(FB->t_now <= FB->t1)
                        {
                            aim_position = FB->vs*FB->t_now + FB->acc*FB->t_now*FB->t_now/2;
                            *target_position = FB->now_position + FB->direction*aim_position;
                            FB->move_state = 1;
                        }
                        else if(FB->t_now <= FB->t1 + FB->t2)
                        {
                            aim_position = FB->state1_s + FB->vmax*(FB->t_now - FB->t1);
                            *target_position = FB->now_position + FB->direction*aim_position;
                            FB->move_state = 2;
                        }
                        else if(FB->t_now < FB->t1 + FB->t2 + FB->t3)
                        {
                                //float temp_aim_position = aim_position;
                            aim_position = FB->state1_s + FB->state2_s + FB->vmax*(FB->t_now - FB->t1 - FB->t2) - FB->dec*(FB->t_now - FB->t1 - FB->t2)*(FB->t_now - FB->t1 - FB->t2)/2;
                            *target_position = FB->now_position + FB->direction*aim_position;
                            FB->move_state = 3;
                        }
                    }
                }


                else if(FB->mode == DEC_EQU_DEC)         /**先减速,再匀速,最后减速*/
                {
                    if(*mode != Position_Mode)          //为位置模式，程序不可用
                    {
                        if(FB->t_now <= FB->t1)
                        {
                            aim_position = FB->vs*FB->t_now - FB->dec*FB->t_now*FB->t_now/2;
                            *target_position = FB->now_position + FB->direction*aim_position;
                            FB->move_state = 1;
                        }
                        else if(FB->t_now <= FB->t1 + FB->t2)
                        {
                            aim_position = FB->state1_s + FB->vmax*(FB->t_now - FB->t1);
                            *target_position = FB->now_position + FB->direction*aim_position;
                            FB->move_state = 2;
                            if(!FB->deviation_flag && (FB->t_now - FB->t1) >= deviation_b*FB->t2 &&
                                ((*now_position > *last_target_position && FB->direction == 1) ||
                                (*now_position < *last_target_position && FB->direction == -1)))
                            {
                                FB->deviation_flag = true;
                                deviation_pos = fabs(*now_position - *last_target_position);
                                deviation_t = deviation_pos/FB->vmax;
                                if(deviation_t >= FB->t2 - (FB->t_now - FB->t1))
                                {
                                    deviation_t = FB->t2 - (FB->t_now - FB->t1);
                                }
                                FB->t2 -= deviation_t;
                                FB->t_all -= deviation_t;
                                FB->now_position += deviation_pos*FB->direction;
                                *target_position = FB->now_position + FB->direction*aim_position;
                                *last_target_position = *target_position - FB->direction*FB->vmax;
                                FB->state2_s = FB->vmax*FB->t2;
                            }
                        }
                        else if(FB->t_now < FB->t1 + FB->t2 + FB->t3)
                        {
                            aim_position = FB->state1_s + FB->state2_s + FB->vmax*(FB->t_now - FB->t1 - FB->t2) - FB->dec*(FB->t_now - FB->t1 - FB->t2)*(FB->t_now - FB->t1 - FB->t2)/2;
                            *target_position = FB->now_position + FB->direction*aim_position;
                            FB->move_state = 3;
                        }
                        else
                        {
                            FB->move_state = 4;
                        }

                        if(FB->direction == 1 && FB->move_state >= 3)
                        {
                            if(*now_position >= FB->pos - tiqian_pos || (*now_position - FB->pos_last < 0.5*minp && FB->j == 10))
                            {
                                FB->move_state = 0;
                                *last_target_position = *now_position;
                                *target_position = *last_target_position;
                                *axis_busy = 0;
                                *run_next = 1;
                                FB->run_flag = false;
                                FB->Active = false;
                                FB->Done = true;
                                FB->CommandAborted = false;
                            }
                            else if(*target_position - *last_target_position < special_minv)
                            {
                                FB->move_state = 4;
                                *target_position = *last_target_position + special_minv;
                            }

                        }
                        else if(FB->direction == -1 && FB->move_state >= 3)
                        {
                            if(*now_position <= FB->pos + tiqian_pos || (FB->pos_last - *now_position < 0.5*minp && FB->j == 10))
                            {
                                FB->move_state = 0;
                                *last_target_position = *now_position;
                                *target_position = *last_target_position;
                                *axis_busy = 0;
                                *run_next = 1;
                                FB->run_flag = false;
                                FB->Active = false;
                                FB->Done = true;
                                FB->CommandAborted = false;
                            }
                            else if(*last_target_position - *target_position < special_minv)
                            {
                                FB->move_state = 4;
                                *target_position = *last_target_position - special_minv;
                            }

                        }
