                        aim_position = FB->state1_s + FB->vmax*FB->t2 + FB->vmax*FB->t3 - FB->dec*FB->t3*FB->t3/2 + FB->now_vel*FB->t4
                                        + FB->now_vel*(FB->t_now - FB->t1 - FB->t2 - FB->t3 - FB->t4) + FB->acc*(FB->t_now - FB->t1 - FB->t2 - FB->t3 - FB->t4)*(FB->t_now - FB->t1 - FB->t2 - FB->t3 - FB->t4)/2;
                        *target_position = FB->now_position + FB->direction*aim_position;
                        FB->move_state = 5;
                    }
                }

            }
        }
        else			//S型曲线
        {
